CREATE FUNCTION public.notify_new_notification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    PERFORM pg_notify('notifications_channel', row_to_json(NEW)::text);
    RETURN NEW;
END;
$$;


